using System.Net;
using System.Net.Http.Json;
using UrlShortener.Application.Links;
using Xunit;

namespace UrlShortener.IntegrationTests;

public sealed class LinkNormalizationHttpTests
{
    [Fact]
    public async Task CreateLink_returns_normalized_destination_and_redirects_to_it()
    {
        using var factory = new ApiFactory();
        using var client = factory.Client();
        const string normalized = "https://example.com/path?keep=1";

        using var createResponse = await client.PostAsJsonAsync("/api/v1/links", new
        {
            longUrl = "HTTPS://Example.COM:443/path?utm_source=campaign&keep=1"
        });

        Assert.Equal(HttpStatusCode.Created, createResponse.StatusCode);
        var link = await createResponse.Content.ReadFromJsonAsync<LinkResponse>();
        Assert.NotNull(link);
        Assert.Equal(normalized, link.LongUrl);

        using var redirectResponse = await client.GetAsync($"/{link.Code}");

        Assert.Equal(HttpStatusCode.Redirect, redirectResponse.StatusCode);
        Assert.Equal(normalized, redirectResponse.Headers.Location?.OriginalString);
    }
}
